-- Rolled-back test for 0040 (write, test in a rolled-back transaction, dry-run, push). Job B.3: discard and trash.
--
--   node scripts/build-sql-test.mjs 0040 && supabase db query --linked -f scripts/test-0040.sql
create temp table r(n serial, check_name text, ok boolean, detail text) on commit drop;
grant all on r to authenticated; grant all on r_n_seq to authenticated;

-- Generated by scripts/build-sql-test.mjs from test-0040.head.sql, 0040, test-0040.body.sql.
begin;
-- Job B.3: discard and trash.
--
-- recordings.discarded_at — a take she threw away before it became cards: Undo on Home's "Writing it up" pill. It is
--   the pipeline's stop signal (checked between stages) and the purge job's to-do if the delete that follows it
--   didn't finish. Discarding before upload (× on the listening screen) never reaches the database.
-- cards.trashed_at, actions.trashed_at — Move to trash. Trashed rows are hidden from every read made with her own
--   token by restrictive select policies, so no screen (app or web) has to remember a filter. The trash view reads
--   them through trashed_items(); trash and restore go through functions too, because an UPDATE whose new row fails a
--   select policy is refused. The service role (pipeline, MCP, purge) bypasses RLS and filters explicitly.
-- Links on a trashed card and its thread membership are hidden, not deleted, so restoring puts them back; thread
--   counts read through thread_cards and so leave trashed cards out.
-- The purge job (apps/web/app/api/cron/purge-trash) deletes trashed rows after 30 days, and a recording's audio once
--   it is discarded or every card and action from it has been in the trash for 30 days.

alter table recordings add column discarded_at timestamptz;
create index recordings_discarded_idx on recordings (discarded_at) where discarded_at is not null;

alter table cards add column trashed_at timestamptz;
create index cards_trashed_idx on cards (creator_id, trashed_at) where trashed_at is not null;

alter table actions add column trashed_at timestamptz;
create index actions_trashed_idx on actions (creator_id, trashed_at) where trashed_at is not null;

create policy "cards: not trashed" on cards as restrictive for select using (trashed_at is null);
create policy "actions: not trashed" on actions as restrictive for select using (trashed_at is null);
-- Through her own token a trashed card isn't visible, so "both cards visible" is "neither end is trashed".
create policy "card_links: both ends live" on card_links as restrictive for select
  using (exists (select 1 from cards where id = card_a) and exists (select 1 from cards where id = card_b));
create policy "thread_cards: card live" on thread_cards as restrictive for select
  using (exists (select 1 from cards where id = card_id));

-- Move an idea to the trash. Other ideas from the same recording stay. If it was the recording's last live idea,
-- the recording's to-dos go with it, stamped with the same time so restore_card brings back exactly those.
create function trash_card(p_card uuid) returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me text := auth.jwt() ->> 'sub';
  rec uuid;
  at timestamptz := now();
  carried int := 0;
begin
  update cards set trashed_at = at
   where id = p_card and creator_id = me and trashed_at is null
  returning recording_id into rec;
  if not found then return null; end if;
  if rec is not null and not exists (select 1 from cards where recording_id = rec and trashed_at is null) then
    update actions set trashed_at = at where recording_id = rec and creator_id = me and trashed_at is null;
    get diagnostics carried = row_count;
  end if;
  return jsonb_build_object('card', p_card, 'actions', carried, 'trashed_at', at);
end $$;

create function restore_card(p_card uuid) returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  me text := auth.jwt() ->> 'sub';
  rec uuid;
  was timestamptz;
begin
  select recording_id, trashed_at into rec, was from cards where id = p_card and creator_id = me and trashed_at is not null;
  if not found then return false; end if;
  update cards set trashed_at = null where id = p_card;
  if rec is not null then
    update actions set trashed_at = null where recording_id = rec and creator_id = me and trashed_at = was;
  end if;
  return true;
end $$;

create function trash_action(p_action uuid) returns boolean
language sql
security definer
set search_path = public
as $$
  with t as (
    update actions set trashed_at = now()
     where id = p_action and creator_id = (auth.jwt() ->> 'sub') and trashed_at is null
    returning 1
  ) select exists (select 1 from t);
$$;

create function restore_action(p_action uuid) returns boolean
language sql
security definer
set search_path = public
as $$
  with t as (
    update actions set trashed_at = null
     where id = p_action and creator_id = (auth.jwt() ->> 'sub') and trashed_at is not null
    returning 1
  ) select exists (select 1 from t);
$$;

-- The trash view: her trashed ideas and to-dos, newest first, with the day each is purged. Deleting a recording from
-- Voice notes reads it too, for the files of trashed rows her own select can't see (frames, an import's original).
create function trashed_items()
returns table (kind text, id uuid, title text, recording_id uuid, project_id uuid, frame_url text, media_path text,
               trashed_at timestamptz, purge_at timestamptz)
language sql
stable
security definer
set search_path = public
as $$
  select * from (
    select 'idea'::text, c.id, c.title, c.recording_id, c.project_id, c.frame_url, c.media_path, c.trashed_at, c.trashed_at + interval '30 days'
      from cards c where c.creator_id = (auth.jwt() ->> 'sub') and c.trashed_at is not null
    union all
    select 'to-do'::text, a.id, a.text, a.recording_id, a.project_id, a.frame_url, null::text, a.trashed_at, a.trashed_at + interval '30 days'
      from actions a where a.creator_id = (auth.jwt() ->> 'sub') and a.trashed_at is not null
  ) t order by 8 desc;
$$;

revoke execute on function trash_card(uuid), restore_card(uuid), trash_action(uuid), restore_action(uuid), trashed_items() from public, anon;
grant execute on function trash_card(uuid), restore_card(uuid), trash_action(uuid), restore_action(uuid), trashed_items() to authenticated;
-- The service role sees every row already; this only keeps the shared deletion code (one call for both) from failing.
grant execute on function trashed_items() to service_role;

-- The public page stops answering for a card in the trash (0034's body, plus the last line).
create or replace function shared_card(p_card_id uuid) returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select jsonb_build_object(
    'id', c.id,
    'title', c.title,
    -- The text form is the title and gist; every other form carries its own words below.
    'gist', case when coalesce(c.shape, 'text') = 'text' then c.gist end,
    'shape', c.shape,
    'quote', c.quote,
    'diagram', c.diagram,
    'board', case when c.board is not null then jsonb_build_object('hook', c.board -> 'hook', 'beats', c.board -> 'beats') end,
    'frame_url', case when c.frame_status = 'done' then c.frame_url end,
    'credit', case when c.frame_attribution ->> 'provider' = 'unsplash' then jsonb_build_object(
      'photographer', c.frame_attribution ->> 'photographer',
      'photographer_url', c.frame_attribution ->> 'photographer_url',
      'photo_url', c.frame_attribution ->> 'photo_url'
    ) end,
    'gradient', p.gradient
  )
    from cards c
    join projects p on p.id = c.project_id
   where c.id = p_card_id
     and c.shared_at is not null
     and c.trashed_at is null;
$$;


-- Fixtures, as the service role: one recording with two ideas and a to-do, another with one idea and a to-do, a
-- link between the first two ideas, both in a thread, the first one shared.
do $$
declare
  me text := 'user_3JfYR4D8eJVCL3yieXStYYoqwaH';
  r1 uuid; r2 uuid; a uuid; b uuid; c uuid; t1 uuid; t2 uuid; th uuid;
begin
  insert into recordings (creator_id, source, storage_path, status) values (me, 'phone', 'test/0040-a.m4a', 'done') returning id into r1;
  insert into recordings (creator_id, source, storage_path, status) values (me, 'phone', 'test/0040-b.m4a', 'done') returning id into r2;
  insert into cards (creator_id, recording_id, title, gist, play_from_ms, confidence) values (me, r1, 'Trash A', 'g', 0, 0.9) returning id into a;
  insert into cards (creator_id, recording_id, title, gist, play_from_ms, confidence) values (me, r1, 'Trash B', 'g', 1000, 0.9) returning id into b;
  insert into cards (creator_id, recording_id, title, gist, play_from_ms, confidence) values (me, r2, 'Trash C', 'g', 0, 0.9) returning id into c;
  insert into actions (creator_id, recording_id, text) values (me, r1, 'To-do from A/B') returning id into t1;
  insert into actions (creator_id, recording_id, text) values (me, r2, 'To-do from C') returning id into t2;
  insert into card_links (card_a, card_b, creator_id) values (least(a, b), greatest(a, b), me);
  insert into threads (creator_id, title) values (me, 'Trash thread') returning id into th;
  insert into thread_cards (thread_id, card_id) values (th, a), (th, b);
  update cards set shared_at = now() where id = a;
  perform set_config('t.r1', r1::text, true); perform set_config('t.r2', r2::text, true);
  perform set_config('t.a', a::text, true); perform set_config('t.b', b::text, true); perform set_config('t.c', c::text, true);
  perform set_config('t.t1', t1::text, true); perform set_config('t.t2', t2::text, true); perform set_config('t.th', th::text, true);

  update recordings set discarded_at = now() where id = r2;
  insert into r values (default, 'recordings.discarded_at takes a time', (select discarded_at is not null from recordings where id = r2), r2::text);
  update recordings set discarded_at = null where id = r2;
end $$;

select set_config('request.jwt.claims', '{"sub":"user_3JfYR4D8eJVCL3yieXStYYoqwaH","role":"authenticated"}', true);
set local role authenticated;
do $$
declare
  a uuid := current_setting('t.a')::uuid; b uuid := current_setting('t.b')::uuid; c uuid := current_setting('t.c')::uuid;
  t1 uuid := current_setting('t.t1')::uuid; t2 uuid := current_setting('t.t2')::uuid; th uuid := current_setting('t.th')::uuid;
  res jsonb; n int; ok boolean;
begin
  -- A has a sibling (B): it goes alone; the recording's to-do stays.
  res := trash_card(a);
  insert into r values (default, 'trash_card trashes the idea', res ->> 'card' = a::text, res::text);
  select count(*) into n from cards where id = a;
  insert into r values (default, 'a trashed idea is hidden from her reads', n = 0, n::text);
  select count(*) into n from cards where id = b;
  insert into r values (default, 'its sibling from the same recording stays', n = 1, n::text);
  select count(*) into n from actions where id = t1;
  insert into r values (default, 'with a live sibling, the recording''s to-do stays', n = 1 and (res ->> 'actions')::int = 0, res::text);
  select count(*) into n from card_links where a in (card_a, card_b);
  insert into r values (default, 'links on a trashed idea are hidden', n = 0, n::text);
  select count(*) into n from thread_cards where thread_id = th;
  insert into r values (default, 'thread counts leave the trashed idea out', n = 1, n::text);
  insert into r values (default, 'a trashed idea''s public page stops answering', shared_card(a) is null, coalesce(shared_card(a)::text, 'null'));
  select count(*) into n from trashed_items() where id = a and kind = 'idea' and purge_at = trashed_at + interval '30 days';
  insert into r values (default, 'the trash view lists it, with its purge day', n = 1, n::text);
  res := trash_card(a);
  insert into r values (default, 'trashing twice is a no-op', res is null, coalesce(res::text, 'null'));

  -- C is the last idea of its recording: its to-do goes with it, and comes back with it.
  res := trash_card(c);
  select count(*) into n from actions where id = t2;
  insert into r values (default, 'the last idea of a recording carries its to-dos to the trash', n = 0 and (res ->> 'actions')::int = 1, res::text);
  select count(*) into n from trashed_items() where id = t2 and kind = 'to-do';
  insert into r values (default, 'the carried to-do is in the trash view', n = 1, n::text);
  ok := restore_card(c);
  select count(*) into n from actions where id = t2;
  insert into r values (default, 'restoring the idea brings its carried to-dos back', ok and n = 1 and exists (select 1 from cards where id = c), n::text);

  ok := restore_card(a);
  select count(*) into n from card_links where a in (card_a, card_b);
  insert into r values (default, 'restore puts the links back', ok and n = 1, n::text);
  select count(*) into n from thread_cards where thread_id = th;
  insert into r values (default, 'restore puts the thread membership back', n = 2, n::text);

  -- To-dos on their own.
  ok := trash_action(t1);
  select count(*) into n from actions where id = t1;
  insert into r values (default, 'trash_action hides a to-do', ok and n = 0, n::text);
  ok := restore_action(t1);
  select count(*) into n from actions where id = t1;
  insert into r values (default, 'restore_action brings it back', ok and n = 1, n::text);

  -- A direct update to trashed_at is refused: the new row fails the select policy.
  begin
    update cards set trashed_at = now() where id = b;
    insert into r values (default, 'trashing goes through trash_card, not a direct update', false, 'updated');
  exception when others then
    insert into r values (default, 'trashing goes through trash_card, not a direct update', true, sqlerrm);
  end;
end $$;
reset role;

-- Another creator can't trash or restore her ideas, or see her trash.
select set_config('request.jwt.claims', '{"sub":"user_someone_else","role":"authenticated"}', true);
set local role authenticated;
do $$
declare b uuid := current_setting('t.b')::uuid; res jsonb; n int;
begin
  res := trash_card(b);
  insert into r values (default, 'another creator can''t trash her idea', res is null, coalesce(res::text, 'null'));
  select count(*) into n from trashed_items();
  insert into r values (default, 'another creator sees none of her trash', n = 0, n::text);
end $$;
reset role;

do $$
declare n int;
begin
  select count(*) into n from cards where id = current_setting('t.b')::uuid and trashed_at is null;
  insert into r values (default, 'her idea is untouched by the other creator', n = 1, n::text);
end $$;

select n, case when ok then 'pass' else 'FAIL' end as result, check_name, detail from r order by n;
rollback;
